 {'machine_type':'n2-custom-12-131072-ext','vcpus':12,'memory_GiB':128,'hourly_usd':str(base+32*D('0.00955')),'condition':'memory-only; no additional CPU quota required; not applied or boot-tested'},
 {'machine_type':'n2-custom-12-196608-ext','vcpus':12,'memory_GiB':192,'hourly_usd':str(base+96*D('0.00955')),'condition':'memory-only; no additional CPU quota required; not applied or boot-tested'},
